import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.Boholvbs.js";const g=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1791661258000}'),o={name:"guide/index.md"};function n(r,t,l,d,h,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>json-tool allows you to quickly format JSON content with a click of a button, and much more:</p><ul><li><strong>JSON validation</strong> — shows an error message warning about invalid JSON.</li><li><strong>Clipboard</strong> — buttons to paste and copy JSON easily.</li><li><strong>Search</strong> — search through the JSON and the result (provided by CodeMirror).</li><li><strong>File upload</strong> — upload a JSON file.</li><li><strong>Table view</strong> — inspect your JSON as a table.</li><li><strong>Shape view</strong> — inspect the JSON shape and statistics.</li><li><strong>Dark mode</strong> and a <strong>history drawer</strong>.</li></ul><p>The tool is available as a web app and as an Electron desktop app.</p><h2 id="open-the-app" tabindex="-1">Open the app <a class="header-anchor" href="#open-the-app" aria-label="Permalink to &quot;Open the app&quot;">​</a></h2><p>You can use the hosted version at <a href="https://marabesi.github.io/json-tool" target="_blank" rel="noreferrer">marabesi.github.io/json-tool</a>, or run it locally.</p><h2 id="basic-usage" tabindex="-1">Basic usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic usage&quot;">​</a></h2><ol><li><p>Open the app and paste or type JSON into the working editor on the left.</p></li><li><p>The editor on the right shows the formatted result as you type.</p></li><li><p>Use the tabs in the header to switch between the views:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Route</th><th>What it shows</th></tr></thead><tbody><tr><td>home</td><td><code>/</code></td><td>Format and validate editors</td></tr><tr><td>table</td><td><code>/table</code></td><td>The JSON as a table</td></tr><tr><td>shape</td><td><code>/schema</code></td><td>JSON shape and statistics</td></tr><tr><td>settings</td><td><code>/settings</code></td><td>Application settings</td></tr></tbody></table></li><li><p>Toggle <strong>validate json</strong> and <strong>sync scroll</strong>, and switch <strong>dark mode</strong> from the header.</p></li></ol><h2 id="run-it-locally" tabindex="-1">Run it locally <a class="header-anchor" href="#run-it-locally" aria-label="Permalink to &quot;Run it locally&quot;">​</a></h2><p>Install the dependencies and start the development server:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>The app runs at <code>http://localhost:3000</code>. To run the Electron desktop app together with the dev server use <code>pnpm dev</code>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/guide/editor">Editor (home)</a></li><li><a href="/docs/guide/table">Table view</a></li><li><a href="/docs/guide/shape">Shape view</a></li><li><a href="/docs/guide/settings">Settings</a></li></ul>`,14)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
